
/**
 * Chat API Types
 *
 * Defines the data exchanged between the Node.js backend
 * and the FastAPI chat endpoint.
 */

/**
 * Request body accepted by the chat API.
 */
export interface ChatRequest {
    /** The message submitted by the user. */
    message: string;
}

/**
 * Successful response returned by the FastAPI chat endpoint.
 */
export interface ChatServiceResponse {
    /** Text generated by the configured local AI model. */
    message: string;

    /** Inference provider identifier, currently "ollama". */
    provider: string;
}
